async (page) => {
  const passed=[]; const check=(ok,name)=>{if(!ok)throw Error(name);passed.push(name)};
  const url='http://127.0.0.1:5189/tests/fixtures/desktop.html?scene=potato&width=440&canvas=1';
  await page.goto(url);await page.locator('.potato-character .potato-sprite[data-ready=true]').waitFor();
  await page.emulateMedia({reducedMotion:'reduce'});
  check(await page.locator('.potato-motion').evaluate(e=>getComputedStyle(e).animationName==='none'),'system reduced motion respected');
  await page.emulateMedia({reducedMotion:'no-preference'});
  await page.locator('.potato-widget').hover();
  await page.getByRole('button',{name:'土豆战神换装',exact:true}).click();await page.getByRole('button',{name:'装备少女粉机甲',exact:true}).click();await page.keyboard.press('Escape');
  await page.evaluate(async()=>{await window.emUse.settings({scene:'buddy'});await window.emUse.settings({scene:'potato'});});
  check(await page.evaluate(async()=>(await window.emUse.getState()).settings.potatoSkin)==='pink','scene switch preserves independent skin');
  await page.locator('.potato-widget').hover();await page.getByRole('button',{name:'土豆战神更多玩法',exact:true}).click();
  await page.locator('.potato-play-grid button').filter({hasText:'装备锅盖'}).click();
  await page.evaluate(()=>window.emUse.settings({scene:'buddy'}));
  await page.locator('.buddy-widget').waitFor();
  await page.evaluate(()=>window.emUse.settings({scene:'potato'}));
  await page.locator('.potato-character').waitFor();
  check(await page.locator('.potato-character').getAttribute('data-action')==='idle','scene unmount clears persistent pose');
  await page.locator('.potato-widget').hover();
  await page.locator('.potato-resize.se').focus();await page.keyboard.press('ArrowUp');
  check(await page.evaluate(async()=>(await window.emUse.getState()).settings.windowWidth)===450,'keyboard resize delegates to shared settings');
  await page.mouse.move(200,200);await page.keyboard.down('Control');await page.mouse.wheel(0,-40);await page.keyboard.up('Control');
  check(await page.evaluate(async()=>(await window.emUse.getState()).settings.windowWidth)>450,'modifier wheel uses shared resize');
  await page.goto(url+'&update=available&platform=macos');
  await page.locator('.potato-widget').hover();
  await page.getByRole('button',{name:/机甲补给箱：新版本/}).click();
  check(await page.getByRole('dialog',{name:'土豆整备站 · 版本更新'}).isVisible(),'dedicated update prop opens shared letter');
  check(await page.getByRole('button',{name:'前往下载',exact:true}).isVisible(),'mac update retains manual-download contract');
  await page.getByRole('button',{name:'稍后更新，关闭来信',exact:true}).click();
  await page.route('**/assets/potato/armor-1-atlas.png',route=>route.abort());
  await page.goto(url+'&quota=none');
  await page.locator('.potato-character .potato-asset-error').waitFor();
  check(await page.locator('.potato-quota').innerText().then(s=>s.includes('—')),'failed art does not invent quota');
  await page.unroute('**/assets/potato/armor-1-atlas.png');
  await page.locator('.potato-character').getByRole('button',{name:'重试',exact:true}).click();
  await page.locator('.potato-character .potato-sprite[data-ready=true]').waitFor();
  check(await page.locator('.potato-character .potato-asset-error').count()===0,'asset retry recovers actual canvas');
  return passed;
}
